"""
btop Resource Monitor Theme Updater
"""

import re
from config import BTOP_DIR


def update_btop(pal):
    BTOP_DIR.mkdir(parents=True, exist_ok=True)
    themes_dir = BTOP_DIR / "themes"
    themes_dir.mkdir(parents=True, exist_ok=True)
    theme_file = themes_dir / "material-you.theme"

    content = f"""# Material You Dynamic Theme for btop
# Auto-generated by change-wallpaper using materialyoucolor

# Main background, empty for terminal default, need to be empty if you want transparent background
theme[main_bg]="{pal['surface']}"

# Main text color
theme[main_fg]="{pal['on_surface']}"

# Title color for boxes
theme[title]="{pal['primary']}"

# Highlight color for keyboard shortcuts
theme[hi_fg]="{pal['tertiary']}"

# Background color of selected item in processes box
theme[selected_bg]="{pal['primary_container']}"

# Foreground color of selected item in processes box
theme[selected_fg]="{pal['on_primary_container']}"

# Color of inactive/disabled text
theme[inactive_fg]="{pal['outline']}"

# Misc colors for processes box including mini cpu graphs, details memory graph and details status text
theme[proc_misc]="{pal['secondary']}"

# Cpu box outline color
theme[cpu_box]="{pal['outline_variant']}"

# Memory/disks box outline color
theme[mem_box]="{pal['outline_variant']}"

# Net up/down box outline color
theme[net_box]="{pal['outline_variant']}"

# Processes box outline color
theme[proc_box]="{pal['outline_variant']}"

# Box divider line and small boxes line color
theme[div_line]="{pal['outline_variant']}"

# Temperature graph colors
theme[temp_start]="{pal['teal']}"
theme[temp_mid]="{pal['yellow']}"
theme[temp_end]="{pal['error']}"

# CPU graph colors
theme[cpu_start]="{pal['primary']}"
theme[cpu_mid]="{pal['tertiary']}"
theme[cpu_end]="{pal['error']}"

# Mem/Disk free meter
theme[free_start]="{pal['green']}"
theme[free_mid]="{pal['teal']}"
theme[free_end]="{pal['primary']}"

# Mem/Disk cached meter
theme[cached_start]="{pal['secondary']}"
theme[cached_mid]="{pal['tertiary']}"
theme[cached_end]="{pal['purple']}"

# Mem/Disk available meter
theme[available_start]="{pal['teal']}"
theme[available_mid]="{pal['primary']}"
theme[available_end]="{pal['yellow']}"

# Mem/Disk used meter
theme[used_start]="{pal['primary']}"
theme[used_mid]="{pal['yellow']}"
theme[used_end]="{pal['error']}"

# Download graph colors
theme[download_start]="{pal['teal']}"
theme[download_mid]="{pal['primary']}"
theme[download_end]="{pal['tertiary']}"

# Upload graph colors
theme[upload_start]="{pal['purple']}"
theme[upload_mid]="{pal['secondary']}"
theme[upload_end]="{pal['peach']}"
"""
    theme_file.write_text(content, encoding="utf-8")

    btop_conf = BTOP_DIR / "btop.conf"
    if btop_conf.is_file():
        try:
            txt = btop_conf.read_text(encoding="utf-8")
            if 'color_theme = "material-you"' not in txt:
                if re.search(r"^color_theme\s*=", txt, flags=re.MULTILINE):
                    txt = re.sub(r"^color_theme\s*=.*$", 'color_theme = "material-you"', txt, flags=re.MULTILINE)
                else:
                    txt = 'color_theme = "material-you"\n' + txt
                btop_conf.write_text(txt, encoding="utf-8")
        except Exception as e:
            print(f"  [Note] btop.conf update: {e}")
